insert into public.site_faqs (slug,question,answer,keywords,source_paths,embedding,active,updated_at) values
('arte','아르떼뮤지엄 부산은 어떤 곳인가요?','아르떼뮤지엄 부산은 영도구 해양로247번길 29에 있는 몰입형 미디어아트 전시 공간입니다. 빛·소리·향으로 자연과 부산의 풍경을 경험하며, report의 [4] 카드에서 상세 소개와 공식 홈페이지를 확인할 수 있습니다.',array['아르떼뮤지엄','아르떼 뮤지엄','arte museum','영도 미디어아트'],array['report.html'],null,true,now()),
('museum1','뮤지엄 원은 어떤 곳인가요?','뮤지엄 원은 해운대구 센텀서로 20에 있는 미디어 전문 현대미술관입니다. LED로 둘러싸인 공간의 영상과 설치 작품을 감상할 수 있으며, report의 [3] 카드에서 상세 소개와 공식 홈페이지를 확인할 수 있습니다.',array['뮤지엄 원','뮤지엄원','museum1','museum 1','센텀 미디어아트'],array['report.html'],null,true,now()),
('hurshim','허심청은 어떤 곳인가요?','허심청은 동래구 온천장로107번길 32에 있는 도시형 온천 시설입니다. 다양한 온천탕과 찜질·휴식 공간을 이용할 수 있습니다. report의 [5] 카드에서 상세 내용을 볼 수 있으며 이용 시간·요금은 공식 홈페이지를 확인해 주세요.',array['허심청','동래온천','온천욕','온천','찜질'],array['report.html'],null,true,now()),
('report-api','Report는 어떤 API로 업데이트되나요?','Report는 한국관광공사_국문 관광정보 서비스_GW와 한국관광공사_웰니스관광정보 API를 사용합니다. 부산 6곳의 주소·상세 소개와 팝업의 제공 사진을 갱신하며 카드의 녹색 픽셀 이미지는 고정합니다. 초록 LED는 두 API 정상 응답, 노랑은 확인 중·부분 연결, 빨강은 응답 확인 불가를 뜻합니다. 응답은 최대 30분 캐시하므로 실시간 운영·예약 가능 여부를 보증하지 않습니다. 인증키는 서버에서만 사용합니다.',array['공공데이터','api','데이터 연결','실시간','자동 갱신','업데이트','led'],array['report.html#resource-api-title'],null,true,now()),
('report-upcoming','추가 구현 예정 공간은 어디인가요?','Report에는 F1963, 고은사진미술관, 부산근현대역사관, 영화의전당, 부산영화체험박물관, 부산문화회관, 깡깡이예술마을, 흰여울문화마을, 부산박물관, 복천박물관, 도모헌, 을숙도생태공원 등 부산 12곳을 추가 구현 예정으로 소개합니다. 아직 상세 카드와 API 연동이 완료된 목록은 아닙니다.',array['구현 예정','추가 예정','예정 목록','next destinations','f1963','고은사진미술관','도모헌','깡깡이'],array['report.html#resource-planned-title'],null,true,now()),
('report-pixel','관광지 카드 이미지는 어떤 스타일인가요?','Report의 관광지 6곳은 녹색 계열의 1:1 픽셀 아트 카드로 통일했습니다. 이미지에 마우스를 올리면 밝아지고, 클릭하면 Windows 95 탐색기 스타일의 상세 팝업이 열립니다. API가 갱신되어도 카드의 픽셀 이미지는 유지됩니다.',array['픽셀','픽셀 이미지','8비트','8bit','카드 이미지','녹색 이미지'],array['report.html'],null,true,now()),
('profile','김준철은 어떤 사람인가요?','김준철은 대학에서 신학을, 대학원에서 종교철학을 공부했습니다. 대한성공회 부산교구 성직청원자이며 AI를 활용한 로컬 관광 콘텐츠·서비스 제작 역량을 기르고 있습니다.',array['김준철','누구','소개','전공','root'],array['index.html'],null,true,now()),
('tour-resources','선정 관광 자원을 알려주세요.','Report의 부산 관광 자원은 총 여섯 곳입니다. [1] 부산현대미술관, [2] 부산시립미술관, [3] 뮤지엄 원, [4] 아르떼뮤지엄 부산, [5] 허심청, [6] 부산어린이대공원 치유의 숲 순서로, 예술 감상에서 온천·자연 속 휴식으로 이어지도록 배치했습니다.',array['관광','자원','추천','미술관','report','몇 곳','여섯 곳','6곳'],array['report.html'],null,true,now()),
('moca','부산현대미술관은 어떤 곳인가요?','부산현대미술관은 을숙도의 생태환경과 동시대 예술이 맞닿는 서부산의 공립미술관입니다. 현대미술 전시, 어린이예술도서관, 을숙도 생태 탐방을 함께 경험할 수 있습니다.',array['현대미술관','moca','을숙도'],array['report.html'],null,true,now()),
('bma','부산시립미술관은 현재 운영하나요?','부산시립미술관은 부산 미술과 국내외 현대미술을 연결하는 공립미술관입니다. 공식 홈페이지의 2026년 10월 29일 확인 기준으로 본관과 이우환공간은 정상 운영 중입니다. 방문 전 최신 전시·운영 안내를 공식 홈페이지에서 확인해 주세요.',array['시립미술관','이우환'],array['report.html'],null,true,now()),
('forest','치유의 숲은 어떤 곳인가요?','부산어린이대공원 치유의 숲은 성지곡수원지와 편백림을 걷는 도심 속 웰니스 공간입니다. 편백숲 걷기, 호흡과 명상, 수원지 산책을 대표 체험으로 소개합니다.',array['치유의 숲','어린이대공원','편백','성지곡'],array['report.html'],null,true,now()),
('company','딸깍상사는 어떤 회사인가요?','딸깍상사는 AI·관광·콘텐츠를 중심으로 부산의 장소와 이야기를 콘텐츠와 서비스로 바꾸는 크리에이티브 컴퍼니입니다. 원칙은 “반복 업무는 AI에게, 방향과 최종 책임은 사람에게”입니다.',array['딸깍상사','회사','브랜드','about'],array['about.html'],null,true,now()),
('contents','Contents에는 어떤 작업이 있나요?','Contents에는 공공데이터 API를 활용한 슬로웨이브 부산을 포함한 프로젝트 다섯 가지와 뿌 초기 캐릭터 디자인, 부산 홍보 포스터가 있습니다. AI 영상 제작 연습 8편, AI 아이돌 실험 3편, 엘라 브이로그와 부산 배경 퍼포먼스, 액션 프리비즈와 스타일 영상도 볼 수 있습니다. 상단 분류 링크에서 원하는 작업으로 바로 이동할 수 있습니다.',array['콘텐츠','contents','ai 제작','제작 연습','영상 연습','모션 스터디'],array['contents.html'],null,true,now()),
('ppoo','부산에 떨어진 뿌는 무엇인가요?','부산에 떨어진 뿌는 우주선 고장으로 부산에 불시착한 외계인이 부산의 음식과 사투리, 예술과 온천을 경험하는 로컬 관찰 예능 IP입니다. Contents의 캐릭터·포스터 섹션에서 초기 설정 시트와 두 장의 장면 이미지를 볼 수 있습니다.',array['뿌','ppoo','외계인'],array['contents.html#ppoo-project'],null,true,now()),
('ella','엘라 브이로그는 어디에 있나요?','Contents의 브이로그·퍼포먼스 섹션에는 약 56초 분량의 엘라의 부산 당일치기와 부산 배경 퍼포먼스 영상이 있습니다. 음소거로 자동 반복 재생되며 영상의 소리 버튼을 누르면 음성을 들을 수 있습니다.',array['엘라','브이로그','퍼포먼스'],array['contents.html#story-films'],null,true,now()),
('action-previz','액션 프리비즈는 무엇인가요?','액션 프리비즈 섹션에는 rect-rush-10s 원본과 캐릭터·공간 적용 실험 영상이 함께 있습니다. 회색 무도가와 레이스 무도가 캐릭터 시트, 스카이브리지 공간 이미지도 배치했습니다.',array['액션','프리비즈 원본','rect','무도가'],array['contents.html#action-previz'],null,true,now()),
('busan-posters','부산 홍보 포스터를 볼 수 있나요?','Contents의 부산 홍보 포스터 항목에는 상어의 형상과 북항 야경을 결합한 포스터, 세일러 캐릭터를 앞세운 포스터 두 작품이 있습니다. 이미지를 누르면 원본 비율로 크게 볼 수 있습니다.',array['포스터','홍보 이미지'],array['contents.html#busan-posters'],null,true,now()),
('artour-character','아르투어부산 캐릭터와 초기 구상을 알려주세요.','SNS 페이지에는 아르투어부산의 예술·웰니스 초기 구상과 씨걸이 캐릭터 설명이 있습니다. 푸른 베레모와 크로스백을 공유하는 귀여운 기본형, 실제 갈매기의 질감을 살린 실사형 시트를 함께 볼 수 있습니다.',array['초기 구상','초기 콘셉트','초기 컨셉','씨걸이 캐릭터','갈매기 캐릭터'],array['sns.html#artour-character'],null,true,now()),
('bukang','집에 가자 부캉아는 어떤 게임인가요?','집에 가자 부캉아는 북항 수로를 배경으로 한 Unity 3D 횡스크롤 액션 게임입니다. 물대포와 파도, 다섯 유형의 관람객과 150초 뒤 등장하는 보스를 구현했습니다. Contents에서 실행 화면과 제작 내용을 볼 수 있으며 게임의 웹 배포는 준비 중입니다.',array['부캉','게임','북항','unity'],array['contents.html#bukang-project'],null,true,now()),
('seagull','씨걸이의 부산 예술지도는 무엇인가요?','씨걸이의 부산 예술지도는 다섯 예술 공간의 방문 안내, 전시 소식, 연계 산책 코스를 탐색하는 웹사이트입니다. Contents의 예술지도 열기 링크에서 로그인 없이 둘러볼 수 있습니다. 운영·전시 자료는 2026년 10월 19일 조사 기준입니다.',array['씨걸','예술지도','예술 지도','seagull'],array['contents.html#seagull-project'],null,true,now()),
('frame','FRAME 스튜디오는 어떤 도구인가요?','FRAME은 사진, 3D 마네킹과 제품을 배치하고 카메라 구도를 조절해 PNG로 저장하는 프리비즈 도구입니다. Contents의 스튜디오 실행 버튼으로 열 수 있고 사진은 브라우저 안에서 처리됩니다. 사진의 입체감은 간이 깊이 표현이며 실제 3D 스캔은 아닙니다.',array['frame','프리비즈','스튜디오','3d','마네킹'],array['contents.html#frame-project'],null,true,now()),
('social','아르투어부산 SNS 채널은 어디인가요?','아르투어부산은 부산의 풍경과 일상을 예술의 시선으로 소개하는 로컬 아트 여행 채널입니다. 사이트에는 X → YouTube → Instagram → Facebook → 네이버 블로그 순서로 다섯 채널을 안내합니다. 카드뉴스·숏폼·장소 기록을 다루며 SNS 페이지와 공통 푸터에서 각 채널로 이동할 수 있습니다.',array['아르투어부산','아르투어 부산','sns','인스타그램','유튜브','네이버 블로그','페이스북','facebook','트위터','5채널'],array['sns.html'],null,true,now()),
('slowwave','슬로웨이브 부산은 무엇인가요?','슬로웨이브 부산은 한국관광공사 웰니스관광정보와 부산축제정보 공공데이터 API로 부산의 쉼과 축제를 연결하는 여행 추천 웹서비스입니다. Contents의 [5] 프로젝트에 있는 웹사이트 보기 링크로 이용할 수 있습니다. Report의 관광지 API 연동과는 별도의 서비스입니다.',array['슬로웨이브','slowwave','웰니스 축제','축제 여행'],array['contents.html#slowwave-project'],null,true,now()),
('programs','관광지 체험 프로그램을 알려주세요.','Report 카드의 이미지를 눌러 탐색기를 연 다음 체험 프로그램 폴더를 선택하세요. 미술관은 전시·미디어아트 감상, 허심청은 온천욕·찜질·휴식, 어린이대공원 치유의 숲은 숲길·수원지 산책을 소개합니다. 일정과 예약·요금은 공식 홈페이지에서 확인해야 합니다.',array['체험 프로그램','프로그램','체험','교육 프로그램'],array['report.html'],null,true,now())
